  perform create_register(v_user, '{"type": "loan", "data": {"name": "RCBC loan (Nina card)", "lender_name": "RCBC", "account_code": "2220", "interest_account": "7520", "book": "Store", "principal": 163000.0, "method": "straight-line", "installment_amount": 3377.29, "term_months": 60, "start_date": "2026-05-25", "notes": "Go-live record. Straight-line: total interest 39,637.40; 6 of 60 paid before Nov 1, 2026. Release date not given; start date = first due date.", "installments": [{"seq": 1, "due_date": "2026-05-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": true}, {"seq": 2, "due_date": "2026-06-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": true}, {"seq": 3, "due_date": "2026-07-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": true}, {"seq": 4, "due_date": "2026-08-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": true}, {"seq": 5, "due_date": "2026-09-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": true}, {"seq": 6, "due_date": "2026-10-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": true}, {"seq": 7, "due_date": "2026-11-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": false}, {"seq": 8, "due_date": "2026-12-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": false}, {"seq": 9, "due_date": "2027-01-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": false}, {"seq": 10, "due_date": "2027-02-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": false}, {"seq": 11, "due_date": "2027-03-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": false}, {"seq": 12, "due_date": "2027-04-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": false}, {"seq": 13, "due_date": "2027-05-25", "principal": 2716.67, "interest": 660.62, "paid_before_go_live": false}, {"seq": 14, "due_date": "2027-06-25", "principal": 2716.67, "interest": 660.62, "paid_