end $$;

-- Check: each loan with its opening balance (principal less installments paid before go-live)
select l.name, l.account_code, l.principal, count(i.*) as rows, count(i.*) filter (where i.paid_before_go_live) as paid_before_go_live,
       l.principal - coalesce(sum(i.principal) filter (where i.paid_before_go_live), 0) as opening_balance
from loans l join loan_installments i on i.loan_id = l.id where l.account_code in ('2210', '2220') group by l.id order by l.account_code;
